import{_ as e,o as n,c as s,a3 as t}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"需求、约束与质量属性","description":"把 Agent 产品目标转成可验证的功能需求、约束、质量属性场景和架构驱动因素。","frontmatter":{"title":"需求、约束与质量属性","description":"把 Agent 产品目标转成可验证的功能需求、约束、质量属性场景和架构驱动因素。","verified_at":"2026-08-06","source":["https://www.iso.org/standard/78176.html","https://www.sei.cmu.edu/library/quality-attribute-workshop-qaw-third-edition/","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/architecture/system-architecture/requirements-constraints-quality-attributes.md","filePath":"py-agent/architecture/system-architecture/requirements-constraints-quality-attributes.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/system-architecture/requirements-constraints-quality-attributes.md"};function r(i,a,p,o,h,c){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="需求、约束与质量属性" tabindex="-1">需求、约束与质量属性 <a class="header-anchor" href="#需求、约束与质量属性" aria-label="Permalink to &quot;需求、约束与质量属性&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 架构不能从“选 LangGraph 还是多 Agent”开始。架构首先服务用户任务，并在成本、延迟、安全、数据和组织能力等约束内工作。需求告诉系统做什么，约束限定可选空间，质量属性定义系统要做到什么程度；三者共同形成架构驱动因素。</p><p>本章建立系统设计的输入；项目层怎样把这些输入冻结为共同交付契约，见<a href="/py-agent/architecture/delivery-evolution/project-scope-acceptance">项目范围与验收标准</a>，评测数据和指标怎样落地见<a href="/py-agent/quality/agent-evaluation/evaluation-goals-datasets">评测目标与数据集</a>。</p><h2 id="_1-四类架构输入" tabindex="-1">1. 四类架构输入 <a class="header-anchor" href="#_1-四类架构输入" aria-label="Permalink to &quot;1. 四类架构输入&quot;">​</a></h2><h3 id="_1-1-业务目标" tabindex="-1">1.1 业务目标 <a class="header-anchor" href="#_1-1-业务目标" aria-label="Permalink to &quot;1.1 业务目标&quot;">​</a></h3><p>业务目标说明为什么建设系统，例如降低客服处理时间、提高研究报告覆盖度或让用户用自然语言查询数据。目标应能连接到业务指标，不能只写“引入 AI”。</p><h3 id="_1-2-功能需求" tabindex="-1">1.2 功能需求 <a class="header-anchor" href="#_1-2-功能需求" aria-label="Permalink to &quot;1.2 功能需求&quot;">​</a></h3><p>功能需求描述用户可观察能力：接受什么输入、产生什么结果、调用哪些业务动作、由谁确认。Agent 的“会思考”不是功能；“根据订单事实生成可核验退款建议”才是。</p><h3 id="_1-3-约束" tabindex="-1">1.3 约束 <a class="header-anchor" href="#_1-3-约束" aria-label="Permalink to &quot;1.3 约束&quot;">​</a></h3><p>约束是不能自由优化的边界，例如数据不得离开指定地域、必须复用现有身份系统、只能访问只读数据库、三个月内交付、模型上下文有限。约束应有来源和复查条件，避免把暂时习惯伪装成永久限制。</p><h3 id="_1-4-质量属性" tabindex="-1">1.4 质量属性 <a class="header-anchor" href="#_1-4-质量属性" aria-label="Permalink to &quot;1.4 质量属性&quot;">​</a></h3><p>质量属性描述功能之外的可测行为：正确性、可用性、延迟、安全、可恢复性、可观测性、可修改性和成本。它们经常互相冲突，需要显式排序。</p><h2 id="_2-从用户任务定义功能" tabindex="-1">2. 从用户任务定义功能 <a class="header-anchor" href="#_2-从用户任务定义功能" aria-label="Permalink to &quot;2. 从用户任务定义功能&quot;">​</a></h2><h3 id="_2-1-actor、目标与结果" tabindex="-1">2.1 Actor、目标与结果 <a class="header-anchor" href="#_2-1-actor、目标与结果" aria-label="Permalink to &quot;2.1 Actor、目标与结果&quot;">​</a></h3><p>每个需求记录主体、触发、输入、成功结果、失败结果和外部副作用。多轮对话只是交互形式，真正验收对象仍是用户目标。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主体：已认证售后专员</span></span>
<span class="line"><span>触发：提交订单号和退款原因</span></span>
<span class="line"><span>结果：生成退款建议、证据和风险项</span></span>
<span class="line"><span>副作用：未经专员确认不得创建退款</span></span>
<span class="line"><span>失败：事实不足时指出缺失信息，不得猜测金额</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_2-2-正常与异常路径" tabindex="-1">2.2 正常与异常路径 <a class="header-anchor" href="#_2-2-正常与异常路径" aria-label="Permalink to &quot;2.2 正常与异常路径&quot;">​</a></h3><p>除成功路径外，覆盖模糊输入、冲突信息、依赖超时、权限不足、用户取消、重复请求和部分成功。Agent 最危险的需求缺口往往出现在“模型不确定时应做什么”。</p><h3 id="_2-3-完成定义" tabindex="-1">2.3 完成定义 <a class="header-anchor" href="#_2-3-完成定义" aria-label="Permalink to &quot;2.3 完成定义&quot;">​</a></h3><p>对问答任务，完成可能是带来源回答；对执行任务，完成是业务终态，而不是模型说“已完成”。状态必须由权威业务系统确认。</p><h2 id="_3-约束模型" tabindex="-1">3. 约束模型 <a class="header-anchor" href="#_3-约束模型" aria-label="Permalink to &quot;3. 约束模型&quot;">​</a></h2><h3 id="_3-1-技术约束" tabindex="-1">3.1 技术约束 <a class="header-anchor" href="#_3-1-技术约束" aria-label="Permalink to &quot;3.1 技术约束&quot;">​</a></h3><p>现有 API、数据库、模型供应商、运行环境和协议版本。技术约束要区分真正不可改变的外部依赖与团队暂时偏好。</p><h3 id="_3-2-数据与合规约束" tabindex="-1">3.2 数据与合规约束 <a class="header-anchor" href="#_3-2-数据与合规约束" aria-label="Permalink to &quot;3.2 数据与合规约束&quot;">​</a></h3><p>数据分类、地域、保留、删除、租户隔离、审计和模型供应商处理政策。这类硬约束应在路由和数据层强制，不留给模型判断。</p><h3 id="_3-3-业务与风险约束" tabindex="-1">3.3 业务与风险约束 <a class="header-anchor" href="#_3-3-业务与风险约束" aria-label="Permalink to &quot;3.3 业务与风险约束&quot;">​</a></h3><p>预算、响应时间、人工人员、可逆性、损失上限和允许自动化程度。高金额或不可逆动作可能必须人工批准。</p><h3 id="_3-4-组织约束" tabindex="-1">3.4 组织约束 <a class="header-anchor" href="#_3-4-组织约束" aria-label="Permalink to &quot;3.4 组织约束&quot;">​</a></h3><p>团队技能、值班能力、交付时间和系统所有权。复杂框架只有在团队能测试、观测和恢复时才是可用选项。</p><h2 id="_4-质量属性场景" tabindex="-1">4. 质量属性场景 <a class="header-anchor" href="#_4-质量属性场景" aria-label="Permalink to &quot;4. 质量属性场景&quot;">​</a></h2><p>“系统要安全、快速、稳定”不可验收。一个质量属性场景包含：来源、刺激、环境、对象、响应和度量。</p><h3 id="_4-1-性能场景" tabindex="-1">4.1 性能场景 <a class="header-anchor" href="#_4-1-性能场景" aria-label="Permalink to &quot;4.1 性能场景&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>来源：交互用户</span></span>
<span class="line"><span>刺激：提交含 5 个附件的研究请求</span></span>
<span class="line"><span>环境：正常峰值 20 个并发任务</span></span>
<span class="line"><span>对象：研究 Agent</span></span>
<span class="line"><span>响应：2 秒内返回已接受和计划，持续输出进度</span></span>
<span class="line"><span>度量：首反馈 p95 &lt;= 2 秒；完整结果 p95 &lt;= 5 分钟</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_4-2-可靠性场景" tabindex="-1">4.2 可靠性场景 <a class="header-anchor" href="#_4-2-可靠性场景" aria-label="Permalink to &quot;4.2 可靠性场景&quot;">​</a></h3><p>模型端点 30 秒不可用时，已接受任务保持可恢复状态，不重复外发副作用；端点恢复后 10 分钟内清空积压。</p><h3 id="_4-3-安全场景" tabindex="-1">4.3 安全场景 <a class="header-anchor" href="#_4-3-安全场景" aria-label="Permalink to &quot;4.3 安全场景&quot;">​</a></h3><p>普通租户上传含间接 Prompt Injection 的文档时，系统不得读取其他租户数据或调用未授权写工具，所有拒绝有审计证据。</p><h3 id="_4-4-可修改性场景" tabindex="-1">4.4 可修改性场景 <a class="header-anchor" href="#_4-4-可修改性场景" aria-label="Permalink to &quot;4.4 可修改性场景&quot;">​</a></h3><p>替换一个模型供应商时，业务用例和工具实现无需修改；适配器与评测更新可在两周内完成并独立回滚。</p><h2 id="_5-agent-特有质量属性" tabindex="-1">5. Agent 特有质量属性 <a class="header-anchor" href="#_5-agent-特有质量属性" aria-label="Permalink to &quot;5. Agent 特有质量属性&quot;">​</a></h2><h3 id="_5-1-任务质量" tabindex="-1">5.1 任务质量 <a class="header-anchor" href="#_5-1-任务质量" aria-label="Permalink to &quot;5.1 任务质量&quot;">​</a></h3><p>包括正确性、完整性、忠实性、引用和工具轨迹。它们用版本化数据集评测，不以单个演示样例证明。</p><h3 id="_5-2-可控性" tabindex="-1">5.2 可控性 <a class="header-anchor" href="#_5-2-可控性" aria-label="Permalink to &quot;5.2 可控性&quot;">​</a></h3><p>系统有明确停止条件、预算、工具权限、确认点和取消语义。可控性决定 Agent 失败时影响能否被限制。</p><h3 id="_5-3-可解释证据" tabindex="-1">5.3 可解释证据 <a class="header-anchor" href="#_5-3-可解释证据" aria-label="Permalink to &quot;5.3 可解释证据&quot;">​</a></h3><p>需要保存来源、工具结果、策略判定、模型和版本。模型生成的一段“解释”不能替代真实运行证据。</p><h3 id="_5-4-适应性与漂移" tabindex="-1">5.4 适应性与漂移 <a class="header-anchor" href="#_5-4-适应性与漂移" aria-label="Permalink to &quot;5.4 适应性与漂移&quot;">​</a></h3><p>模型、索引和外部内容会变化。架构需支持版本、离线评测、金丝雀、监控与回滚。</p><h2 id="_6-优先级与权衡" tabindex="-1">6. 优先级与权衡 <a class="header-anchor" href="#_6-优先级与权衡" aria-label="Permalink to &quot;6. 优先级与权衡&quot;">​</a></h2><h3 id="_6-1-硬门槛" tabindex="-1">6.1 硬门槛 <a class="header-anchor" href="#_6-1-硬门槛" aria-label="Permalink to &quot;6.1 硬门槛&quot;">​</a></h3><p>越权率为零、数据地域、金额上限等不能被其他指标抵消。先筛掉不满足硬约束的方案。</p><h3 id="_6-2-优化目标" tabindex="-1">6.2 优化目标 <a class="header-anchor" href="#_6-2-优化目标" aria-label="Permalink to &quot;6.2 优化目标&quot;">​</a></h3><p>在合格方案间比较质量、延迟、成本、交付速度和可维护性。每个权衡都要写明受益者和代价，例如更强模型提高质量但增加 p95 和费用。</p><h3 id="_6-3-场景权重" tabindex="-1">6.3 场景权重 <a class="header-anchor" href="#_6-3-场景权重" aria-label="Permalink to &quot;6.3 场景权重&quot;">​</a></h3><p>按任务频率、用户价值和失败损失设置权重，但高风险长尾不应被高频低风险平均掩盖。关键 Slice 单独设门禁。</p><h2 id="_7-架构驱动因素" tabindex="-1">7. 架构驱动因素 <a class="header-anchor" href="#_7-架构驱动因素" aria-label="Permalink to &quot;7. 架构驱动因素&quot;">​</a></h2><p>不是所有需求都影响架构。驱动因素通常具备高业务价值、高技术风险、跨组件影响或难以事后修改，例如：</p><ul><li>必须恢复长时间工作流；</li><li>写操作需人工批准且不可重复；</li><li>数据必须租户和地域隔离；</li><li>高峰时仍需低首反馈延迟；</li><li>模型和供应商必须可替换。</li></ul><p>驱动因素决定接下来优先设计哪些边界、状态、接口和部署拓扑。</p><h2 id="_8-填写后的需求卡" tabindex="-1">8. 填写后的需求卡 <a class="header-anchor" href="#_8-填写后的需求卡" aria-label="Permalink to &quot;8. 填写后的需求卡&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能力：售后退款建议</span></span>
<span class="line"><span>用户：已认证售后专员</span></span>
<span class="line"><span>输入：订单号、原因、附件</span></span>
<span class="line"><span>输出：建议、事实证据、缺失项、风险等级</span></span>
<span class="line"><span>副作用：确认后创建退款任务</span></span>
<span class="line"><span>约束：境内处理；单次金额 &lt;= 500 元；只读订单接口</span></span>
<span class="line"><span>质量：关键事实准确率 &gt;= 99%；禁止越权调用 = 0</span></span>
<span class="line"><span>性能：首反馈 p95 &lt;= 2 秒；建议 p95 &lt;= 20 秒</span></span>
<span class="line"><span>恢复：模型超时后任务可重试，确认过的动作不得重复</span></span>
<span class="line"><span>观测：每次建议关联来源、工具调用、策略版本和 Trace</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>这些阈值是示例，真实值需由业务、风险和基线数据共同决定。</p><h2 id="_9-验证与变更" tabindex="-1">9. 验证与变更 <a class="header-anchor" href="#_9-验证与变更" aria-label="Permalink to &quot;9. 验证与变更&quot;">​</a></h2><p>将功能需求映射到验收测试，将质量场景映射到评测、压力、安全和恢复实验。建立追踪关系：需求 ID → 架构决策 → 实现组件 → 验证证据。</p><p>当用户任务、数据分类、模型能力、流量或风险容忍变化时复查驱动因素。架构文档若没有与评测和运行数据连接，很快会失真。</p><h2 id="_10-常见误区" tabindex="-1">10. 常见误区 <a class="header-anchor" href="#_10-常见误区" aria-label="Permalink to &quot;10. 常见误区&quot;">​</a></h2><ol><li><strong>先画组件图再补需求</strong>：组件没有可解释的存在理由。</li><li><strong>把“使用 LangGraph”写成需求</strong>：这是候选实现，不是用户目标。</li><li><strong>质量属性只有形容词</strong>：无法测试，也无法做取舍。</li><li><strong>所有指标取平均</strong>：高风险失败被低风险成功掩盖。</li><li><strong>约束永不复查</strong>：临时限制会固化成不必要复杂度。</li></ol><h2 id="_11-评审清单" tabindex="-1">11. 评审清单 <a class="header-anchor" href="#_11-评审清单" aria-label="Permalink to &quot;11. 评审清单&quot;">​</a></h2><ul><li>业务目标是否连接到可观察用户结果；</li><li>正常、失败、不确定和副作用路径是否定义；</li><li>约束是否有来源、强制位置和复查条件；</li><li>质量属性是否写成带环境与度量的场景；</li><li>硬门槛是否与优化目标分开；</li><li>架构驱动因素是否真正跨组件或难以修改；</li><li>每项关键需求是否有明确验证证据。</li></ul><p>架构设计的第一份产物不是图，而是一组可验证的驱动因素。只有先说清系统必须完成什么、不能违反什么以及如何判断做得好，后续组件和技术选择才有客观依据。</p>`,71)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
